import{_ as a,o as t,c as s,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Angular package format","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/libraries/angular-package-format.md","filePath":"en/tools/libraries/angular-package-format.md"}'),o={name:"en/tools/libraries/angular-package-format.md"};function n(l,e,r,d,p,c){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="angular-package-format" tabindex="-1">Angular package format <a class="header-anchor" href="#angular-package-format" aria-label="Permalink to &quot;Angular package format&quot;">​</a></h1><p>This document describes the Angular Package Format (APF). APF is an Angular specific specification for the structure and format of npm packages that is used by all first-party Angular packages (<code>@angular/core</code>, <code>@angular/material</code>, etc.) and most third-party Angular libraries.</p><p>APF enables a package to work seamlessly under most common scenarios that use Angular. Packages that use APF are compatible with the tooling offered by the Angular team as well as wider JavaScript ecosystem. It is recommended that third-party library developers follow the same npm package format.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>APF is versioned along with the rest of Angular, and every major version improves the package format. You can find the versions of the specification prior to v13 in this <a href="https://docs.google.com/document/d/1CZC2rcpxffTDfRDs6p1cfbmKNLA6x5O-NtkJglDaBVs/preview" target="_blank" rel="noreferrer">google doc</a>.</p></div><h2 id="why-specify-a-package-format" tabindex="-1">Why specify a package format? <a class="header-anchor" href="#why-specify-a-package-format" aria-label="Permalink to &quot;Why specify a package format?&quot;">​</a></h2><p>In today&#39;s JavaScript landscape, developers consume packages in many different ways, using many different toolchains (webpack, Rollup, Rolldown, esbuild, etc.). These tools may understand and require different inputs - some tools may be able to process the latest ES language version, while others may benefit from directly consuming an older ES version.</p><p>The Angular distribution format supports all of the commonly used development tools and workflows, and adds emphasis on optimizations that result either in smaller application payload size or faster development iteration cycle (build time).</p><p>Developers can rely on the Angular CLI to produce packages in the Angular Package Format. See the <a href="/en/tools/libraries/creating-libraries">Creating Libraries</a> guide for more details.</p><h2 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File layout&quot;">​</a></h2><p>The following example shows a simplified version of the <code>@angular/core</code> package&#39;s file layout, with an explanation for each file in the package.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node_modules/@angular/core</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├── README.md</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├── package.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├── fesm2022</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ ├── core.mjs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ ├── core.mjs.map</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ ├── testing.mjs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ └── testing.mjs.map</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">└── types</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ ├── core.d.ts</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ ├── testing.d.ts</span></span></code></pre></div><p>This table describes the file layout under <code>node_modules/@angular/core</code> annotated to describe the purpose of files and directories:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>README.md</code></td><td style="text-align:left;">Package README, used by npmjs web UI.</td></tr><tr><td style="text-align:left;"><code>package.json</code></td><td style="text-align:left;">Primary <code>package.json</code>, describing the package itself as well as all available entrypoints and code formats. This file contains the &quot;exports&quot; mapping used by runtimes and tools to perform module resolution.</td></tr><tr><td style="text-align:left;"><code>fesm2022/</code> <br>   ─ <code>core.mjs</code> <br>   ─ <code>core.mjs.map</code> <br>   ─ <code>testing.mjs</code> <br>   ─ <code>testing.mjs.map</code></td><td style="text-align:left;">Code for all entrypoints in flattened (FESM) ES2022 format, along with source maps.</td></tr><tr><td style="text-align:left;"><code>types/</code> <br>   ─ <code>core.d.ts</code> <br>   ─ <code>testing.d.ts</code></td><td style="text-align:left;">Bundled TypeScript type definitions for all public entrypoints.</td></tr></tbody></table><h3 id="package-json" tabindex="-1"><code>package.json</code> <a class="header-anchor" href="#package-json" aria-label="Permalink to &quot;\`package.json\`&quot;">​</a></h3><p>The primary <code>package.json</code> contains important package metadata, including the following:</p><ul><li><p>It <a href="#esm-declaration">declares</a> the package to be in EcmaScript Module (ESM) format</p></li><li><p>It contains an <code>&quot;exports&quot;</code> field which defines the available source code formats of all entrypoints</p></li><li><p>It contains <a href="#legacy-resolution-keys">keys</a> which define the available source code formats of the primary <code>@angular/core</code> entrypoint, for tools which do not understand <code>&quot;exports&quot;</code>. These keys are considered deprecated, and could be removed as the support for <code>&quot;exports&quot;</code> rolls out across the ecosystem.</p></li><li><p>It declares whether the package contains <a href="#side-effects">side effects</a></p></li></ul><h3 id="esm-declaration" tabindex="-1">ESM declaration <a class="header-anchor" href="#esm-declaration" aria-label="Permalink to &quot;ESM declaration&quot;">​</a></h3><p>The top-level <code>package.json</code> contains the key:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;module&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This informs resolvers that code within the package is using EcmaScript Modules as opposed to CommonJS modules.</p><h3 id="exports" tabindex="-1"><code>&quot;exports&quot;</code> <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;\`&quot;exports&quot;\`&quot;">​</a></h3><p>The <code>&quot;exports&quot;</code> field has the following structure:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;exports&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;./schematics/*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./schematics/*.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;./package.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./package.json&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./types/core.d.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./fesm2022/core.mjs&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;./testing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./types/testing.d.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./fesm2022/testing.mjs&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Of primary interest are the <code>&quot;.&quot;</code> and the <code>&quot;./testing&quot;</code> keys, which define the available code formats for the <code>@angular/core</code> primary entrypoint and the <code>@angular/core/testing</code> secondary entrypoint, respectively. For each entrypoint, the available formats are:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Formats</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;">Typings (<code>.d.ts</code> files)</td><td style="text-align:left;"><code>.d.ts</code> files are used by TypeScript when depending on a given package.</td></tr><tr><td style="text-align:left;"><code>default</code></td><td style="text-align:left;">ES2022 code flattened into a single source.</td></tr></tbody></table><p>Tooling that is aware of these keys may preferentially select a desirable code format from <code>&quot;exports&quot;</code>.</p><p>You might also want to expose additional static files, such as Sass mixins or pre-compiled CSS, that are not part of the JavaScript-based entry points.</p><p>For more information, see <a href="/en/tools/libraries/creating-libraries#managing-assets-in-a-library">Managing assets in a library</a>.</p><h3 id="legacy-resolution-keys" tabindex="-1">Legacy resolution keys <a class="header-anchor" href="#legacy-resolution-keys" aria-label="Permalink to &quot;Legacy resolution keys&quot;">​</a></h3><p>In addition to <code>&quot;exports&quot;</code>, the top-level <code>package.json</code> also defines legacy module resolution keys for resolvers that don&#39;t support <code>&quot;exports&quot;</code>. For <code>@angular/core</code> these are:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./fesm2022/core.mjs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;typings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./types/core.d.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>As shown in the preceding code snippet, a module resolver can use these keys to load a specific code format.</p><h3 id="side-effects" tabindex="-1">Side effects <a class="header-anchor" href="#side-effects" aria-label="Permalink to &quot;Side effects&quot;">​</a></h3><p>The last function of <code>package.json</code> is to declare whether the package has <a href="#sideeffects-flag">side effects</a>.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;sideEffects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Most Angular packages should not depend on top-level side effects, and thus should include this declaration.</p><h3 id="entrypoints-and-code-splitting" tabindex="-1">Entrypoints and code splitting <a class="header-anchor" href="#entrypoints-and-code-splitting" aria-label="Permalink to &quot;Entrypoints and code splitting&quot;">​</a></h3><p>Packages in the Angular Package Format contain one primary entrypoint and zero or more secondary entrypoints (for example, <code>@angular/common/http</code>). Entrypoints serve several functions.</p><ol><li><p>They define the module specifiers from which users import code (for example, <code>@angular/core</code> and <code>@angular/core/testing</code>).</p><p>Users typically perceive these entrypoints as distinct groups of symbols, with different purposes or capability.</p><p>Specific entrypoints might only be used for special purposes, such as testing. Such APIs can be separated out from the primary entrypoint to reduce the chance of them being used accidentally or incorrectly.</p></li><li><p>They define the granularity at which code can be lazily loaded.</p><p>Many modern build tools are only capable of &quot;code splitting&quot; (aka lazy loading) at the ES Module level. The Angular Package Format uses primarily a single &quot;flat&quot; ES Module per entry point. This means that most build tooling is not able to split code with a single entry point into multiple output chunks.</p></li></ol><p>The general rule for APF packages is to use entrypoints for the smallest sets of logically connected code possible. For example, the Angular Material package publishes each logical component or set of components as a separate entrypoint - one for Button, one for Tabs, etc. This allows each Material component to be lazily loaded separately, if desired.</p><p>Not all libraries require such granularity. Most libraries with a single logical purpose should be published as a single entrypoint. <code>@angular/core</code> for example uses a single entrypoint for the runtime, because the Angular runtime is generally used as a single entity.</p><h4 id="resolution-of-secondary-entry-points" tabindex="-1">Resolution of secondary entry points <a class="header-anchor" href="#resolution-of-secondary-entry-points" aria-label="Permalink to &quot;Resolution of secondary entry points&quot;">​</a></h4><p>Module resolvers resolve secondary entry points using the <code>&quot;exports&quot;</code> field in the package&#39;s <code>package.json</code> file.</p><p>To learn how to configure secondary entry points in a library, see <a href="/en/tools/libraries/creating-libraries#entry-points">Entry points</a>.</p><h3 id="readme-md" tabindex="-1">README.md <a class="header-anchor" href="#readme-md" aria-label="Permalink to &quot;README.md&quot;">​</a></h3><p>The README file in the Markdown format that is used to display description of a package on npm and GitHub.</p><p>Example README content of @angular/core package:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Angular </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;equals;&amp;equals;&amp;equals;&amp;equals;&amp;equals;&amp;equals;&amp;equals;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The sources for this package are in</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">the main [Angular](https://github.com/angular/angular) repo.Please file issues and pull requests</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">against that repo. License: MIT</span></span></code></pre></div><h2 id="library-compilation-and-package-optimizations" tabindex="-1">Library Compilation and Package Optimizations <a class="header-anchor" href="#library-compilation-and-package-optimizations" aria-label="Permalink to &quot;Library Compilation and Package Optimizations&quot;">​</a></h2><p>This section describes the compilation process for libraries and optimizations that apply to the npm package before publishing the artifact to a registry.</p><h3 id="partial-compilation" tabindex="-1">Partial compilation <a class="header-anchor" href="#partial-compilation" aria-label="Permalink to &quot;Partial compilation&quot;">​</a></h3><p>Libraries in the Angular Package Format must be published in &quot;partial compilation&quot; mode. This is a compilation mode for <code>ngc</code> which produces compiled Angular code that is not tied to a specific Angular runtime version, in contrast to the full compilation used for applications, where the Angular compiler and runtime versions must match exactly.</p><p>To partially compile Angular code, use the <code>compilationMode</code> flag in the <code>angularCompilerOptions</code> property of your <code>tsconfig.json</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  …</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;angularCompilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;compilationMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;partial&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Partially compiled library code is then converted to fully compiled code during the application build process by the Angular CLI.</p><p>If your build pipeline does not use the Angular CLI then refer to the <a href="/en/tools/libraries/creating-libraries#consuming-partial-ivy-code-outside-the-angular-cli">Consuming partial ivy code outside the Angular CLI</a> guide.</p><h3 id="flattening-of-es-modules" tabindex="-1">Flattening of ES modules <a class="header-anchor" href="#flattening-of-es-modules" aria-label="Permalink to &quot;Flattening of ES modules&quot;">​</a></h3><p>The Angular Package Format specifies that code be published in &quot;flattened&quot; ES module format. This significantly reduces the build time of Angular applications as well as download and parse time of the final application bundle. Please check out the excellent post <a href="https://nolanlawson.com/2016/08/15/the-cost-of-small-modules" target="_blank" rel="noreferrer">&quot;The cost of small modules&quot;</a> by Nolan Lawson.</p><p>FESM is a file format created by flattening all ES Modules accessible from an entrypoint into a single ES Module. It&#39;s formed by following all imports from a package and copying that code into a single file while preserving all public ES exports and removing all private imports. However, in some cases, the FESM may depend on shared chunks that are shared between multiple entry points.</p><p>The abbreviated name, FESM, pronounced <em>phe-som</em>, can be followed by a number such as FESM2022. The number refers to the language level of the JavaScript inside the module. Accordingly a FESM2022 file is ESM+ES2022 and includes import/export statements and ES2022 source code.</p><p>When building with the Angular CLI (<code>@angular/build:library</code>), the builder compiles your library with <code>ngc</code> and uses Rolldown to bundle each entry point directly into flattened ES2022 modules in the <code>fesm2022/</code> directory.</p><h3 id="sideeffects-flag" tabindex="-1">&quot;sideEffects&quot; flag <a class="header-anchor" href="#sideeffects-flag" aria-label="Permalink to &quot;&quot;sideEffects&quot; flag&quot;">​</a></h3><p>By default, EcmaScript Modules are side-effectful: importing from a module ensures that any code at the top level of that module should run. This is often undesirable, as most side-effectful code in typical modules is not truly side-effectful, but instead only affects specific symbols. If those symbols are not imported and used, it&#39;s often desirable to remove them in an optimization process known as tree-shaking, and the side-effectful code can prevent this.</p><p>Build tools such as webpack support a flag which allows packages to declare that they do not depend on side-effectful code at the top level of their modules, giving the tools more freedom to tree-shake code from the package. The end result of these optimizations should be smaller bundle size and better code distribution in bundle chunks after code-splitting. This optimization can break your code if it contains non-local side-effects - this is however not common in Angular applications and it&#39;s usually a sign of bad design. The recommendation is for all packages to claim the side-effect free status by setting the <code>sideEffects</code> property to <code>false</code>, and that developers follow the <a href="/en/style-guide">Angular Style Guide</a> which naturally results in code without non-local side-effects.</p><p>More info: <a href="https://github.com/webpack/webpack/tree/main/examples/side-effects" target="_blank" rel="noreferrer">webpack docs on side effects</a></p><h3 id="es2022-language-level" tabindex="-1">ES2022 language level <a class="header-anchor" href="#es2022-language-level" aria-label="Permalink to &quot;ES2022 language level&quot;">​</a></h3><p>ES2022 Language level is now the default language level that is consumed by Angular CLI and other tooling. The Angular CLI down-levels the bundle to a language level that is supported by all targeted browsers at application build time.</p><h3 id="flattening-of-type-definitions-d-ts-bundling" tabindex="-1">Flattening of Type Definitions (<code>.d.ts</code> bundling) <a class="header-anchor" href="#flattening-of-type-definitions-d-ts-bundling" aria-label="Permalink to &quot;Flattening of Type Definitions (\`.d.ts\` bundling)&quot;">​</a></h3><p>As of APF v8, it is recommended to bundle TypeScript definitions. Bundling of type definitions can significantly speed up compilations for users, especially if there are many individual <code>.ts</code> source files in your library.</p><p>Angular uses <a href="https://github.com/sxzz/rolldown-plugin-dts" target="_blank" rel="noreferrer"><code>rolldown-plugin-dts</code></a> to flatten <code>.d.ts</code> files (using <code>rolldown</code>, similar to how FESM files are created).</p><p>Using rolldown for <code>.d.ts</code> bundling is beneficial as it supports code splitting between entry-points. For example, consider you have multiple entrypoints relying on the same shared type, a shared <code>.d.ts</code> file would be created along with the larger flattened <code>.d.ts</code> files. This is desirable and avoids duplication of types.</p><h3 id="tslib" tabindex="-1">Tslib <a class="header-anchor" href="#tslib" aria-label="Permalink to &quot;Tslib&quot;">​</a></h3><p>As of APF v10, it is recommended to list <code>tslib</code> as a direct dependency of your library whenever its compiled output imports runtime helpers from <code>tslib</code>. This is because the <code>tslib</code> version is tied to the TypeScript version used to compile your library. When building with <code>@angular/build:library</code>, the builder automatically adds <code>tslib</code> to <code>dependencies</code> in the generated <code>package.json</code> if the compiled code imports <code>tslib</code>.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>The npm packages of the Angular framework are a good reference point for APF-compliant library packages. Browse the file layout and npm package on UNPKG:</p><ul><li><a href="https://app.unpkg.com/@angular/core@latest" target="_blank" rel="noreferrer">@angular/core package</a></li><li><a href="https://app.unpkg.com/@angular/material@latest" target="_blank" rel="noreferrer">@angular/material package</a></li></ul><h2 id="definition-of-terms" tabindex="-1">Definition of terms <a class="header-anchor" href="#definition-of-terms" aria-label="Permalink to &quot;Definition of terms&quot;">​</a></h2><p>The following terms are used throughout this document intentionally. In this section are the definitions of all of them to provide additional clarity.</p><h3 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h3><p>The smallest set of files that are published to npm and installed together, for example <code>@angular/core</code>. This package includes a manifest called package.json, compiled source code, typescript definition files, source maps, metadata, etc. The package is installed with <code>npm install @angular/core</code>.</p><h3 id="symbol" tabindex="-1">Symbol <a class="header-anchor" href="#symbol" aria-label="Permalink to &quot;Symbol&quot;">​</a></h3><p>A class, function, constant, or variable contained in a module and optionally made visible to the external world via a module export.</p><h3 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h3><p>Short for ECMAScript Modules. A file containing statements that import and export symbols. This is identical to the definition of modules in the ECMAScript spec.</p><h3 id="esm" tabindex="-1">ESM <a class="header-anchor" href="#esm" aria-label="Permalink to &quot;ESM&quot;">​</a></h3><p>Short for ECMAScript Modules (see above).</p><h3 id="fesm" tabindex="-1">FESM <a class="header-anchor" href="#fesm" aria-label="Permalink to &quot;FESM&quot;">​</a></h3><p>Short for Flattened ES Modules and consists of a file format created by flattening all ES Modules accessible from an entry point into a single ES Module. Note that FESM is typically a single file, but it can depend on a shared chunk that is shared with other FESMs.</p><h3 id="module-id" tabindex="-1">Module ID <a class="header-anchor" href="#module-id" aria-label="Permalink to &quot;Module ID&quot;">​</a></h3><p>The identifier of a module used in the import statements (for example, <code>@angular/core</code>). The ID often maps directly to a path on the filesystem, but this is not always the case due to various module resolution strategies.</p><h3 id="module-specifier" tabindex="-1">Module specifier <a class="header-anchor" href="#module-specifier" aria-label="Permalink to &quot;Module specifier&quot;">​</a></h3><p>A module identifier (see above).</p><h3 id="module-resolution-strategy" tabindex="-1">Module resolution strategy <a class="header-anchor" href="#module-resolution-strategy" aria-label="Permalink to &quot;Module resolution strategy&quot;">​</a></h3><p>Algorithm used to convert Module IDs to paths on the filesystem. Node.js has one that is well specified and widely used, TypeScript supports several module resolution strategies, <a href="https://developers.google.com/closure/compiler" target="_blank" rel="noreferrer">Closure Compiler</a> has yet another strategy.</p><h3 id="module-format" tabindex="-1">Module format <a class="header-anchor" href="#module-format" aria-label="Permalink to &quot;Module format&quot;">​</a></h3><p>Specification of the module syntax that covers at minimum the syntax for the importing and exporting from a file. Common module formats are CommonJS (CJS, typically used for Node.js applications) or ECMAScript Modules (ESM). The module format indicates only the packaging of the individual modules, but not the JavaScript language features used to make up the module content. Because of this, the Angular team often uses the language level specifier as a suffix to the module format, (for example, ESM+ES2022 specifies that the module is in ESM format and contains ES2022 code).</p><h3 id="bundle" tabindex="-1">Bundle <a class="header-anchor" href="#bundle" aria-label="Permalink to &quot;Bundle&quot;">​</a></h3><p>An artifact in the form of a single JS file, produced by a build tool (for example, <a href="https://webpack.js.org" target="_blank" rel="noreferrer">webpack</a> or <a href="https://rollupjs.org" target="_blank" rel="noreferrer">Rollup</a>) that contains symbols originating in one or more modules. Bundles are a browser-specific workaround that reduce network strain that would be caused if browsers were to start downloading hundreds if not tens of thousands of files. Node.js typically doesn&#39;t use bundles. Common bundle formats are UMD and System.register.</p><h3 id="language-level" tabindex="-1">Language level <a class="header-anchor" href="#language-level" aria-label="Permalink to &quot;Language level&quot;">​</a></h3><p>The language of the code (ES2022). Independent of the module format.</p><h3 id="entry-point" tabindex="-1">Entry point <a class="header-anchor" href="#entry-point" aria-label="Permalink to &quot;Entry point&quot;">​</a></h3><p>A module intended to be imported by the user. It is referenced by a unique module ID and exports the public API referenced by that module ID. An example is <code>@angular/core</code> or <code>@angular/core/testing</code>. Both entry points exist in the <code>@angular/core</code> package, but they export different symbols. A package can have many entry points.</p><h3 id="deep-import" tabindex="-1">Deep import <a class="header-anchor" href="#deep-import" aria-label="Permalink to &quot;Deep import&quot;">​</a></h3><p>A process of retrieving symbols from modules that are not Entry Points. These module IDs are usually considered to be private APIs that can change over the lifetime of the project or while the bundle for the given package is being created.</p><h3 id="top-level-import" tabindex="-1">Top-Level import <a class="header-anchor" href="#top-level-import" aria-label="Permalink to &quot;Top-Level import&quot;">​</a></h3><p>An import coming from an entry point. The available top-level imports are what define the public API and are exposed in &quot;@angular/name&quot; modules, such as <code>@angular/core</code> or <code>@angular/common</code>.</p><h3 id="tree-shaking" tabindex="-1">Tree-shaking <a class="header-anchor" href="#tree-shaking" aria-label="Permalink to &quot;Tree-shaking&quot;">​</a></h3><p>The process of identifying and removing code not used by an application - also known as dead code elimination. This is a global optimization performed at the application level using tools like <a href="https://rollupjs.org" target="_blank" rel="noreferrer">Rollup</a>, <a href="https://rolldown.rs/" target="_blank" rel="noreferrer">Rolldown</a>, <a href="https://developers.google.com/closure/compiler" target="_blank" rel="noreferrer">Closure Compiler</a>, or <a href="https://github.com/terser/terser" target="_blank" rel="noreferrer">Terser</a>.</p><h3 id="aot-compiler" tabindex="-1">AOT compiler <a class="header-anchor" href="#aot-compiler" aria-label="Permalink to &quot;AOT compiler&quot;">​</a></h3><p>The Ahead of Time Compiler for Angular.</p><h3 id="flattened-type-definitions" tabindex="-1">Flattened type definitions <a class="header-anchor" href="#flattened-type-definitions" aria-label="Permalink to &quot;Flattened type definitions&quot;">​</a></h3><p>The bundled TypeScript definitions generated using tools like <a href="https://api-extractor.com" target="_blank" rel="noreferrer">API Extractor</a> or <a href="https://github.com/sxzz/rolldown-plugin-dts" target="_blank" rel="noreferrer"><code>rolldown-plugin-dts</code></a>.</p>`,112)]))}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
